'use strict';importScripts('data/offline-assets.js');const SHELL='psycholibrary-shell-'+self.STUDY_OFFLINE.version,CHAPTERS='psycholibrary-chapters-v1';
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(SHELL);try{await cache.addAll(self.STUDY_OFFLINE.assets);}catch(e){await caches.delete(SHELL);throw e;}await self.skipWaiting();})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('psycholibrary-shell-')&&key!==SHELL)await caches.delete(key);await self.clients.claim();})()));
self.addEventListener('fetch',event=>{const request=event.request,url=new URL(request.url);if(request.method!=='GET'||url.origin!==self.location.origin)return;const path=url.pathname.replace(/^\//,'')||'index.html';event.respondWith((async()=>{const chapters=await caches.open(CHAPTERS),downloaded=await chapters.match(request,{ignoreSearch:true});if(downloaded&&request.cache!=='reload')return downloaded;const shell=await caches.open(SHELL),controller=new AbortController(),timer=setTimeout(()=>controller.abort(),4500);try{const response=await fetch(request,{signal:controller.signal});if(response.ok&&self.STUDY_OFFLINE.assets.includes(path))await shell.put(request,response.clone());if(response.ok||!self.STUDY_OFFLINE.assets.includes(path))return response;throw Error('Unavailable');}catch(e){const hit=await shell.match(request,{ignoreSearch:true})||await shell.match(path);if(hit)return hit;if(request.mode==='navigate')return await shell.match('study.html')||Response.error();return Response.error();}finally{clearTimeout(timer);}})());});
